<?php
namespace App\Models;use App\Casts\DateOnly;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;
/** Provides training enrollment behavior within the WorkIntel application. */ class TrainingEnrollment extends Model{protected $fillable=['workspace_id','course_id','member_id','status','assigned_at','started_at','completed_at','expires_on','score','certificate_document_id','assigned_by'];/** Defines attribute casting rules for the model. */ protected function casts():array{return ['assigned_at'=>'datetime','started_at'=>'datetime','completed_at'=>'datetime','expires_on'=>DateOnly::class,'score'=>'decimal:2'];}/** Handles the course operation for the current WorkIntel workflow. */ public function course():BelongsTo{return $this->belongsTo(TrainingCourse::class,'course_id');}/** Handles the member operation for the current WorkIntel workflow. */ public function member():BelongsTo{return $this->belongsTo(WorkspaceMember::class,'member_id');}}
